#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""polish_docx_v8.py — edit the user's manuscript docx in place:
 (1) remove ALL bold from non-heading paragraphs and table cells (headings keep their style bold);
 (2) a language pass that reduces defensive/AI phrasing and improves readability, preserving every
     numeric string exactly (so the num!=verification still passes);
 (3) explicit figure/table citations down to the sub-panel level (Figure 2 left/right; Figure 3; S1-S3).
A timestamped backup is made first. Nothing numeric is changed."""
import shutil, datetime, re, docx
SRC = r"H:\眼科论文\眼科3诊断-照护缺口\manuscript\题目3手稿最新版本.docx"
bak = SRC.replace(".docx", f"_backup_{datetime.datetime.now():%Y%m%d_%H%M%S}.docx")
shutil.copy(SRC, bak)

R = {
7: "Whether objectively graded retinal disease corresponds to patient-reported diagnosis and eye-care use has not been characterised in nationally representative data. We combined centrally graded retinal photographs with self-reported diagnoses and eye-examination history from US adults aged ≥40 in NHANES 2005–2008 (n = 6,797), using the 2016 National Health Interview Survey (NHIS) as a contextual benchmark and survey weights with design-based confidence intervals among item responders. Among adults with diabetes and objectively graded retinopathy, 70.2% (63.8–75.9) reported no prior diabetic-eye diagnosis; among those with objectively graded age-related macular degeneration (AMD), 82.2% (77.3–86.2) reported none, including 41.4% (25.3–59.6) with late AMD. Within the diabetic-retinopathy group, 32.4% (25.9–39.7) reported no dilated examination within 12 months. Greater severity was associated with higher reported awareness, and in an exploratory adjusted analysis a recent dilated examination was associated with lower odds of no reported diagnosis (adjusted OR 0.30, 0.10–0.92), although this did not survive multiple-testing correction. Objectively graded AMD prevalence (6.58%) exceeded age-standardised self-report (2.45%), a contextual rather than paired comparison. These findings document substantial discordance between retinal imaging, patient-reported diagnosis and eye-care use in a historical US population and do not by themselves establish clinical underdiagnosis.",
9: "Diabetic retinopathy and age-related macular degeneration (AMD) are leading causes of irreversible vision loss and account for a large share of global blindness and moderate-to-severe visual impairment.¹,² Both are largely asymptomatic until late, yet are detectable on retinal examination and treatable in their advanced forms through glycaemic and blood-pressure control, laser photocoagulation, and anti–vascular endothelial growth factor therapy.³⁻⁵ Their public-health impact therefore depends not only on how much disease exists but on how much of it is recognised and brought into care.",
10: "National surveys have measured the prevalence of these conditions extensively.⁶⁻⁸ More recently they have also begun to measure awareness and undiagnosed disease: recent work has quantified social determinants of diabetic-retinopathy awareness in NHANES 2005–2008,⁹ and the burden of undiagnosed age-related eye disease among older adults has been described elsewhere.¹⁰,¹¹ A persistent obstacle is that most datasets capture only one side of the ledger. Self-report surveys such as the National Health Interview Survey (NHIS) record who has entered the health system but are blind to disease that was never diagnosed.¹² Imaging cohorts record disease that exists but often lack matched self-report of diagnosis and care.",
12: "We therefore aimed to (i) quantify, in US adults ≥40, the proportion of objectively graded retinopathy in diabetes and of AMD that carries no self-reported diagnosis, and the proportion of at-risk people with diabetes not receiving recommended eye care; (ii) describe how this discordance varies with disease severity and across age strata; (iii) examine whether sociodemographic, access, and eye-care-utilisation factors are associated with having no reported diagnosis; and (iv) benchmark the self-reported side against an independent national survey (NHIS 2016) with age-standardisation.",
15: "Of 6,797 examined adults aged ≥40 with retinal photography, 5,704 had a gradable retinopathy image and 5,604 a gradable AMD image (Supplementary Table S1, Figure S1). Because the diagnosis-discordance outcome requires an answer to the corresponding self-report item, all denominators below are responders. Among adults with diabetes and objectively graded retinopathy (n = 319), 313 answered the diabetic-eye item and formed the DR denominator; six non-responders were excluded. Among adults with objectively graded AMD (n = 441), 436 answered the macular-degeneration item (five excluded). Multivariable models were smaller because education and income were missing, not because of the outcome: of the 313 DR responders, 102 lacked education and 30 lacked income, leaving 187 in the complete-case core model; of the 436 AMD responders, 188 lacked education and 42 lacked income, leaving 226 (Supplementary Table S1). Design degrees of freedom were computed with survey::degf() for each subset (Supplementary Table S7b): the DR and AMD responder sets spanned 31 strata with 59 and 61 PSUs (design df 28 and 30), and the complete-case core models retained df 22 and 29. Regression inference used each model's residual degrees of freedom, degf(design) − model rank + 1 (13 for the eye-care model); Supplementary Table S7c reports the design df, rank, residual df, t-multiplier and every coefficient, standard error, confidence interval, raw P and Holm-adjusted P from the same fitted object, so intervals and P values cannot drift apart.",
19: "Among adults with diabetes who had objectively graded retinopathy and answered the item, 70.2% (63.8–75.9) reported no prior diabetic-eye diagnosis (Table 2, Figure 1). Among adults with objectively graded AMD who answered the item, 82.2% (77.3–86.2) reported no prior macular-degeneration diagnosis, and even among those with late AMD — the stage most likely to be symptomatic — 41.4% (25.3–59.6) reported no diagnosis (n = 55). The outcome is the absence of a recalled, patient-reported diagnosis, not a chart-confirmed absence of diagnosis. We do not estimate a diagnosis gap for people with objectively graded retinopathy who do not report diabetes, because the diabetic-eye item (DIQ080) is asked only of people with diabetes; the appropriate denominator is therefore diabetic respondents (n = 313). Extreme-scenario bounds that assign the six DR and five AMD item non-responders first to \"diagnosed\" and then to \"undiagnosed\" move the weighted estimates only marginally (DR 69.2–70.6%, AMD 81.6–82.3%), so the headline gaps are not an artefact of non-response (Supplementary Table S7).",
23: "Self-reported diagnosis rose steeply with retinopathy severity among adults with diabetes — from 16.6% with no gradable retinopathy, to 21.9% mild, 35.6% moderate, and 84.3% severe-or-proliferative disease — and the corresponding diagnosis gap fell from 78.1% (71.3–83.7) for mild, to 64.4% (48.3–77.8) moderate, to 15.7% (5.0–39.7) severe-or-proliferative disease (Figure 2, left panel; Supplementary Table S2). AMD discordance was similarly graded: the gap was higher for early AMD (87.9%, 84.4–90.6, n = 381) than for late AMD (41.4%, 25.3–59.6, n = 55), each computed from its own responder set (Figure 2, right panel). By age stratum, AMD discordance was near-complete at 40–59 years (99.1%, 95.6–99.8), fell to 86.6% (77.8–92.3) at 60–74 and 66.7% (60.1–72.6) at ≥75, whereas the DR gap was flatter (Supplementary Table S2). The severe-DR and late-AMD strata are small and their intervals wide, so the fall in discordance with severity is best read as a graded descriptive pattern rather than a series of individually tested contrasts.",
25: "Reframing around clinically more advanced disease, the diagnosis gap remained substantial at or above the moderate-non-proliferative threshold: among adults with diabetes and moderate-or-worse retinopathy (n = 116) the pooled gap was 53.4% (38.7–67.5), comprising 64.4% (48.3–77.8) for moderate and 15.7% (5.0–39.7) for severe-or-proliferative disease (Figure 2, left panel). For AMD, 41.4% (25.3–59.6) of objectively graded late AMD carried no reported diagnosis. The \"moderate-or-worse\" grouping denotes clinically more advanced disease, not a treatable or immediately blinding category — moderate non-proliferative retinopathy is typically monitored rather than treated — and imaging severity is not a treatment indication. Splitting late AMD, geographic atrophy was undiagnosed in 50.3% (26.6–73.9; n = 32) and exudative/neovascular AMD in 27.7% (8.0–62.9; n = 23); both strata are small with widely overlapping intervals, so this difference is not an established group difference. The two phenotypes also differ in therapy and in treatability at the time these data were collected.",
27: "These covariate analyses are exploratory and describe factors that travel with the patient-reported gap; they are not causal. In survey-adjusted complete-case core models (Table 3), older age was the only factor independently associated with lower odds of no self-reported diagnosis for AMD (aOR 0.93 per year, 95% CI 0.89–0.96; Holm-adjusted P = 0.003). For DR, no covariate reached significance after Holm correction. The family-income association was directionally consistent (aOR > 1 in every specification) but its magnitude and precision varied with missing-data handling: complete-case core aOR 1.34 (0.92–1.96, Holm P = 0.59); adding insurance, 1.39 (0.96–2.00, P = 0.077); dropping education, 1.46 (1.08–1.97, P = 0.017, n = 283); and multiple imputation (m = 20, Rubin-pooled) 1.38 (1.02–1.87, P = 0.037, n = 313), with the income aOR above 1 in all 20 imputations (range 1.24–1.49, SD 0.048). We therefore treat higher income as a tentative, imprecise correlate rather than an established driver. Education and insurance associations were non-significant under every approach (Supplementary Table S4). In the AMD model, insurance was not included because complete separation in the uninsured stratum prevented a stable estimate; the descriptive pattern is reported in Supplementary Table S4 rather than as a fitted term. Overall, we did not detect statistically robust socioeconomic associations with diagnosis discordance, although limited precision precludes excluding clinically meaningful differences.",
29: "Within the diabetic-retinopathy cohort, recent eye-care contact tracked awareness. Unadjusted, 82.0% (70.1–89.9) of adults not examined within 12 months (n = 106) reported no diabetic-eye diagnosis versus 64.5% (55.9–72.2) of those examined (n = 207). This is an exploratory secondary analysis; the adjusted odds ratio with its confidence interval is the primary quantity (full model in Supplementary Table S3). In the fully adjusted model (Table 4, n = 187), a recent dilated examination was associated with lower odds of an unreported diagnosis (aOR 0.30, 0.10–0.92, P = 0.038), but this did not remain significant after correction across the model's nine terms (Holm-adjusted P = 0.27); model-adjusted predicted risk was 81.8% versus 62.4% (a −19.4-percentage-point descriptive difference; Figure S2). The odds ratio, interval and P value come from a single quasi-binomial Wald t test on the model's residual degrees of freedom (df = 13), so they are internally consistent. The one term that survived correction was proliferative severity (aOR 0.05, 0.01–0.24, Holm-adjusted P = 0.010; relative to mild non-proliferative diabetic retinopathy, the reference because all participants had graded retinopathy). An exploratory eye-care × severity interaction gave no evidence of effect modification (aOR 1.61, 0.24–10.79, P = 0.59). Recent dilated examination was therefore associated with lower odds of an unreported diagnosis in the adjusted analysis, although the association did not survive multiple-testing correction; being cross-sectional, the design cannot establish whether examination leads to diagnosis or diagnosis prompts examination. The analogous AMD analysis is not feasible: dilated-examination timing (DIQ360) is collected only for people with diabetes, and only 59 of the 436 AMD responders were diabetic.",
31: "Images were ungradable for 1,093 participants, who differed from gradable participants: they were older (mean 64.5 vs 59.6 years), more often diabetic (22.1% vs 15.9%) and less often high-school-educated (23.2% vs 14.4% <HS) (Supplementary Table S8). To test whether this imbalance biases estimates, we reweighted gradable participants by the inverse probability of a gradable image. A base model (age, sex, race/ethnicity) moved whole-population prevalence only slightly (any retinopathy 9.75% → 9.98%; any AMD 6.58% → 6.87%); an extended model adding diabetes, insurance and education gave 9.75% → 10.13% and 6.58% → 6.77%. The inverse-probability factors were modest (1/P about 1.0–1.8; the smallest predicted gradability probability was 0.57, so the 0.05 floor never bound and no observation was truncated), and the Kish effective sample size of the combined weights (≈3,635–3,656 of 5,704) stayed close to the raw-weight value (≈3,508). This is a limited stability check rather than proof of weight robustness: an unchanged aggregate ESS can coexist with a long weight tail and speaks only to observable differences. The diagnosis gaps themselves were essentially unchanged under IPW (DR 70.2% → 70.2%; AMD 82.2% → 82.0%). The descriptive prevalence and primary discordance proportions are therefore robust to observable differences between gradable and ungradable images, although inverse-probability weighting cannot address unmeasured selection (Supplementary Table S8).",
33: "In NHIS 2016, weighted self-reported prevalence among adults ≥40 was 2.66% (2.40–2.91) for macular degeneration and 1.27% (1.09–1.46) for diabetic retinopathy; 48.7% (47.7–49.7) had seen an eye doctor and 49.9% (48.9–51.0) had a dilated examination within 12 months (Table 5). Self-reported glaucoma (3.97%) and cataract (21.17%) are reported in Supplementary Table S5c and, being outside the objective-versus-reported comparison, are not carried into the main analysis; the NHIS cataract item (\"ever told you had cataract\") is also a different construct from the NHANES cataract-surgery history in Table 1, so the two are not compared directly. Directly age-standardising the NHIS macular-degeneration proportion (2.66% crude) to the NHANES 40+ age structure yielded 2.45% (2.22–2.69) using the full design-based covariance of the age-band estimates; age-and-sex standardisation gave 2.46% (2.22–2.70) (Figure 3; Supplementary Table S5, S5b). The difference between objectively graded AMD (6.58%) and age-standardised self-report persisted after standardisation, but it cannot be attributed specifically to diagnostic unawareness because the surveys differ in calendar period, ascertainment and respondents. NHIS is therefore an auxiliary contextual benchmark, not a paired validation of individual diagnosis status.",
35: "In a nationally representative sample of US adults aged ≥40 examined in 2005–2008, objectively graded retinal abnormalities, patient-reported diagnosis, and eye-care utilisation were substantially discordant. Roughly seven in ten adults with diabetes and graded retinopathy, and more than eight in ten with graded AMD, reported no prior diagnosis; even among those with late AMD, about four in ten reported no diagnosis, and about one third of the highest-risk people with diabetes had not been examined within 12 months. These proportions, the severity gradient and the eye-care association are the study's core contributions.",
36: "The observed discordance is not a direct estimate of clinically undiagnosed disease. Imaging identifies retinal abnormalities under a standardised protocol, whereas the questionnaire captures whether participants recall being told they had a corresponding condition; the two differ in diagnostic threshold, terminology and susceptibility to recall error. Retinal microvascular abnormalities in adults with diabetes are also not necessarily attributable to diabetes alone. Even so, discordance persisted in advanced categories — a 15.7% gap in severe-or-proliferative retinopathy and 41.4% in late AMD — so it cannot be explained solely by the inclusion of mild imaging abnormalities. The small numbers with severe retinopathy and late AMD warrant caution in interpreting these severity-specific estimates.",
37: "Three findings stand out. First, discordance narrowed but did not close with severity: self-reported diabetic-eye diagnosis rose from about 17% without gradable retinopathy to about 84% in proliferative disease, and the AMD gap fell from 87.9% in early to 41.4% in late disease, yet a substantial gap persisted in advanced categories. Second, discordance was broadly distributed across sociodemographic strata: after adjustment we did not detect statistically robust associations with education, income or insurance, with only age significant for AMD and the income association varying in precision with missing-data handling. Third, the eye-care–awareness association was a secondary, exploratory finding: recent dilated examination was associated with a lower likelihood of reporting no prior diagnosis, but the association did not survive multiple-comparison correction, and the cross-sectional design cannot distinguish whether eye-care contact facilitates recognition, whether a known diagnosis prompts examination, or whether both reflect severity and access. These patterns are consistent with, but do not establish, a hypothesis that examination patterns shape diagnostic awareness; because prior diagnosis can itself prompt eye-care visits, the relationship is bidirectional and remains a question for prospective study.",
38: "Our work extends prior NHANES analyses of retinopathy prevalence and awareness.⁶,⁹ Earlier work estimated diabetic-retinopathy prevalence in NHANES 2005–2008⁶ and examined social determinants of DR awareness in the same cycles using NHANES imaging together with the diagnosis questionnaire.⁹ Because that study already paired objective grading with a patient-reported diagnosis in the same respondents, our contribution lies elsewhere: a parallel treatment of DR and AMD with explicit, disease-specific responder denominators; presentation of the patient-reported discordance by clinical severity, including moderate-or-worse retinopathy and late AMD, with confidence intervals; an explicit link between reported diagnosis and recent dilated eye-care use among adults with diabetes, with the reciprocal-direction caveat a cross-section imposes; a systematic set of sensitivity analyses covering survey design, item non-response, covariate missingness and image gradability; and an NHIS comparison used only as auxiliary context. The marked AMD age gradient is not simply a proxy for worse disease in older participants: it persisted after adjustment for AMD stage (0.92 per year) and within a stage-restricted early-AMD sample (Supplementary Table S9), consistent with greater cumulative ophthalmic contact at older ages rather than severity alone. Because the abnormalities that matter are frequently silent and discordance is broad, case-finding cannot rely on symptom- or risk-triggered referral alone; the American Academy of Ophthalmology preferred-practice-pattern and NHANES-based evidence support periodic dilated or imaged examination for people with diabetes.⁴,⁵,¹⁴ These findings motivate evaluation of targeted retinal assessment and diagnosis-communication strategies in contemporary populations. This study did not compare screening strategies, diagnostic yield, false-positive rates, referral burden or cost-effectiveness, so it does not establish the effectiveness or cost-effectiveness of broader population screening.",
39: "Several limitations define the scope of these findings. NHANES retinal imaging covers only adults ≥40, so estimates do not generalise to younger adults with type 1 diabetes, and the design is cross-sectional: we measure a snapshot of diagnostic awareness and care, not time-to-diagnosis or outcomes. \"No self-reported diagnosis\" is not identical to \"never diagnosed\". Respondents may forget or misname a diagnosis, or have it recorded only in an eye-care chart, which would overstate the apparent gap; conversely, a participant may report a diagnosis that was never formally made, which would understate it. Including mild imaging lesions that never reached a threshold a clinician would label as disease would also tend to overstate the apparent diagnosis gap, because such eyes were arguably never candidates for a clinical diagnosis. Missing socioeconomic information substantially reduced the complete-case samples; reduced-covariate, missing-indicator and multiple-imputation models gave income associations in a similar direction, but their precision and significance varied, the imputation did not fully reproduce the complex sampling structure, and neither complete-case analysis nor multiple imputation can exclude bias from unobserved determinants of missingness. We therefore interpret all socioeconomic associations as exploratory and do not regard the direction of the income association as established. Participants with ungradable photographs differed in age, diabetes prevalence and education, and inverse-probability weighting for these observed predictors changed prevalence and the diagnosis gaps only modestly; that analysis depends on the gradability-model specification and cannot account for unmeasured factors affecting both image quality and disease status, so it does not eliminate selection bias. Several strata are small (severe DR n = 31; uninsured AMD n = 14; late-AMD subtypes n = 32/23), producing wide intervals and one non-estimable coefficient, and the AMD eye-care analysis is not feasible because examination timing is collected only for people with diabetes. Finally, the retinal imaging data were collected in 2005–2008, before substantial changes in imaging, screening pathways and treatment availability, and the NHIS benchmark is from 2016, so the cross-survey comparison cannot be attributed purely to under-diagnosis. The findings therefore characterise historical patterns rather than current US prevalence, and validation in contemporary populations with linked clinical diagnoses and imaging would strengthen their relevance.",
41: "In US adults aged ≥40 examined in 2005–2008, objectively graded retinal abnormalities frequently lacked a corresponding patient-reported diagnosis, and a substantial proportion of adults with diabetes and graded retinopathy reported no recent dilated eye examination. Discordance was less pronounced in more advanced disease but remained evident in late AMD and severe retinopathy. These findings describe historical differences between imaging-based classification, diagnostic awareness and eye-care utilisation rather than definitive clinical underdiagnosis or current US practice. Studies with contemporary imaging, linked clinical records and longitudinal eye-care data are needed to determine how these discrepancies arise and whether targeted interventions improve outcomes.",
60: "The authors used an AI coding assistant (QoderWork) to help write and debug the analysis scripts and to assist in drafting and editing the manuscript. All statistical outputs, numbers, code and prose were independently checked by the authors, who take full responsibility for them and confirmed their accuracy before submission. No AI tool meets the ICMJE authorship criteria and none is listed as an author, consistent with ICMJE and Scientific Reports policy.",
}

d = docx.Document(SRC)
for idx, new in R.items():
    p = d.paragraphs[idx]
    p.text = new

# remove bold everywhere outside headings (and in table cells)
def style_is_heading(p):
    s = p.style.name if p.style else ""
    return s.startswith(("Heading", "Title"))
for p in d.paragraphs:
    if style_is_heading(p):
        continue
    for r in p.runs:
        r.bold = False
        r.font.bold = False
for t in d.tables:
    for row in t.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                for r in p.runs:
                    r.bold = False
                    r.font.bold = False

# fix heading capitalisation
for p in d.paragraphs:
    if p.style and p.style.name.startswith("Heading") and p.text.strip().lower() == "competing interests":
        p.text = "Competing interests"

d.save(SRC)
print("edited:", SRC)
print("backup:", bak)
